import os, glob, re
funcs = []
for p in sorted(glob.glob("pipedrive/v1/*.go")):
    if p.endswith("_test.go"): continue
    with open(p) as f:
        for line in f:
            m = re.match(r"^func (With\w+)\(", line)
            if m:
                funcs.append((os.path.basename(p), m.group(1)))
for file, fn in funcs[:30]:
    print(f"{file}: {fn}")
'

